-- Generated by scripts/gen-answers-sql.mjs from snippets/*/meta.json. Do not edit by hand.
-- Safe to run repeatedly. Removing a snippet that past runs used fails on purpose
-- (foreign key from run_questions), so history is never orphaned.

begin;

insert into public.snippet_answers (snippet_id, answer, title, why) values
  ('anagrams', 'O(n!)', 'every rearrangement of a word', 'The used-flags backtracking builds one string per ordering of the n distinct letters.'),
  ('best-under-limit', 'O(2ⁿ)', 'best subset sum under a limit (bitmask)', 'There are 2ⁿ masks, each summed over n bits: n × 2ⁿ. That is still the exponential class.'),
  ('binary-search', 'O(log n)', 'binary search', 'Each comparison discards half of the remaining range.'),
  ('binary-strings', 'O(2ⁿ)', 'every binary string of length n', 'Each position branches into "0" and "1", producing 2ⁿ strings.'),
  ('brackets', 'O(n)', 'balanced brackets', 'Each character is pushed or popped at most once.'),
  ('bst-search', 'O(log n)', 'search a balanced BST', 'The search drops one level per step, and a balanced tree is log n levels tall. An unbalanced tree could degrade to O(n).'),
  ('bubble', 'O(n²)', 'bubble sort', 'Up to n passes, each comparing neighbours across the unsorted part.'),
  ('by-frequency', 'O(n log n)', 'order words by frequency', 'Counting is O(n). Sorting up to n distinct words is O(n log n), and that dominates.'),
  ('count-digits', 'O(log n)', 'count decimal digits', 'Dividing by 10 each pass means the loop runs once per digit, about log₁₀ n times.'),
  ('count-divisors', 'O(√n)', 'count divisors', 'Each divisor d found below √n also gives the partner n / d, so the loop stops at √n.'),
  ('count-max', 'O(n)', 'count copies of the maximum', 'Two loops one after the other: n + n = 2n, and the constant drops out.'),
  ('count-subsets', 'O(2ⁿ)', 'count subsets hitting a target', 'Every element is either taken or skipped: two branches per level, n levels deep.'),
  ('dedupe-list', 'O(n²)', 'dedupe with a list membership test', 'The membership test on a list (in, includes, contains, std::find) is a hidden linear scan, and it runs inside a loop over n items.'),
  ('derangements-brute', 'O(n!)', 'count derangements by enumeration', 'The swap-based search walks the orderings with only a cheap filter at each position. Its worst case is still on the order of n! arrangements.'),
  ('digit-total', 'O(n log n)', 'total digits of 1..n', 'The number i has about log₁₀ i digits. Summed over 1..n, that is about n log n.'),
  ('distance-matrix', 'O(n²)', 'pairwise distance matrix', 'n points produce an n × n table, with O(1) work per cell.'),
  ('doubling-passes', 'O(n log n)', 'full pass per doubling width', 'The outer loop doubles width until it reaches n, about log n times, and each round is a full O(n) pass.'),
  ('drain-front', 'O(n²)', 'drain a list from the front', 'Removing the first element of an array-backed list shifts all the remaining elements, and there are n removals. A deque avoids this.'),
  ('dutch-flag', 'O(n)', 'three-way partition of 0s, 1s, 2s', 'Each step either moves mid forward or moves hi back, so the gap closes within n steps.'),
  ('ends', 'O(1)', 'first and last element', 'Two index reads, whatever the length of the array.'),
  ('equal-pairs', 'O(n²)', 'count equal ordered pairs', 'Two full nested loops over the same input: n × n.'),
  ('factor-pairs', 'O(√n)', 'list factor pairs', 'Each pair (d, n / d) is found from its smaller member, and the smaller member is never above √n.'),
  ('factorial-tree', 'O(n!)', 'n calls to f(n − 1)', 'T(n) = n × T(n − 1), which unrolls to n × (n − 1) × … × 1 = n!.'),
  ('factorial-value', 'O(n)', 'compute n factorial', 'The result is n!, but computing it takes only n − 1 multiplications (treating each multiply as O(1)).'),
  ('fast-pow', 'O(log n)', 'exponentiation by squaring', 'The exponent is halved on every pass. Here n is the exponent, and each multiply is treated as constant time.'),
  ('fenwick', 'O(log n)', 'Fenwick tree prefix sum', 'Each step clears the lowest set bit of i, and i has at most log n bits.'),
  ('floyd-warshall', 'O(n³)', 'all-pairs shortest paths', 'For each of the n intermediate vertices, every one of the n² pairs is relaxed.'),
  ('frequencies', 'O(n)', 'word frequencies', 'Each word costs one average-O(1) hash update.'),
  ('gauss', 'O(1)', 'sum 1..n by formula', 'A closed-form formula replaces the loop: one multiply and one divide for any n.'),
  ('gcd', 'O(log n)', 'Euclid’s gcd', 'The remainder at least halves every two steps, so the loop is logarithmic in the smaller input.'),
  ('gray-code', 'O(2ⁿ)', 'n-bit Gray code', 'It produces one code for each of the 2ⁿ values, with O(1) work per code.'),
  ('grid-sum', 'O(n²)', 'brightness of an n × n image', 'With n as the side length there are n² pixels. The work is linear in the pixel count, so always state what n means.'),
  ('halvings', 'O(log n)', 'halve until one', 'n is cut in half on every pass, so the loop runs about log₂ n times.'),
  ('hanoi', 'O(2ⁿ)', 'Tower of Hanoi', 'There are two recursive calls on n − 1 disks: T(n) = 2T(n − 1) + 1, which is 2ⁿ − 1 moves.'),
  ('harmonic', 'O(n log n)', 'divisor counts by multiples', 'The inner loop runs n / d times. n/1 + n/2 + … + n/n = n × H(n), which is about n ln n.'),
  ('has-duplicate', 'O(n log n)', 'sort, then scan for duplicates', 'Sorting costs O(n log n). The scan afterwards is only O(n), so the sort dominates.'),
  ('hash-get', 'O(1)', 'hash map lookup', 'A hash lookup jumps straight to a bucket. It is O(1) on average; heavy collisions are the rare exception.'),
  ('heap-push', 'O(log n)', 'binary heap insert', 'The new value climbs at most the height of the heap, and a binary heap is log n levels tall.'),
  ('heap-sort', 'O(n log n)', 'sort through a priority queue', 'There are n pushes and n pops, and each heap operation costs O(log n).'),
  ('heaps-algorithm', 'O(n!)', 'permutations by single swaps', 'Heap’s algorithm emits each of the n! orderings exactly once, using one swap between consecutive orderings.'),
  ('insertion', 'O(n²)', 'insertion sort', 'In the worst case (reverse-sorted input), step i shifts i items. It is O(n) on input that is already sorted, but Big O here means the worst case.'),
  ('inversions', 'O(n²)', 'count inversions by brute force', 'Every pair i < j is compared once: n(n − 1) / 2 comparisons.'),
  ('is-prime', 'O(√n)', 'trial-division prime check', 'Divisors are only tried while d × d ≤ n, because any factor above √n pairs with one below it.'),
  ('isqrt-binary', 'O(log n)', 'integer square root by bisection', 'This binary-searches over 0..n instead of climbing one step at a time. The answer is √n, but finding it takes log n steps.'),
  ('isqrt-climb', 'O(√n)', 'integer square root by counting', 'r goes up by one until r² passes n, which takes about √n steps.'),
  ('jump-search', 'O(√n)', 'jump search', 'There are at most √n jumps of size √n, then at most √n single steps inside one block.'),
  ('kadane', 'O(n)', 'maximum subarray (running best)', 'A single pass keeps the best sum ending here and the best sum seen so far.'),
  ('knapsack-naive', 'O(2ⁿ)', '0/1 knapsack without memoisation', 'Each item is taken or skipped, giving up to 2ⁿ paths. Memoising on (i, cap) would make it pseudo-polynomial.'),
  ('lcs', 'O(n²)', 'longest common subsequence table', 'It fills an (n + 1) × (m + 1) table with O(1) work per cell. When both strings have length n, that is n².'),
  ('linear-search', 'O(n)', 'linear search', 'In the worst case the target is last or missing, so every element is checked.'),
  ('linear-times-doubling', 'O(n log n)', 'doubling loop inside a linear loop', 'There are n outer iterations, and each runs an inner loop that doubles j up to n: n × log n.'),
  ('lis-tails', 'O(n log n)', 'longest increasing subsequence (tails)', 'Each of the n values does one binary search into the tails array.'),
  ('longest-palindrome-brute', 'O(n³)', 'longest palindrome by checking every substring', 'There are O(n²) substrings, and each is copied and reversed in O(n).'),
  ('lower-bound', 'O(log n)', 'first index not below target', 'The half-open range [lo, hi) shrinks by half on every pass.'),
  ('matmul', 'O(n³)', 'schoolbook matrix multiply', 'Three nested loops, each running n times.'),
  ('matrix-chain', 'O(n³)', 'matrix-chain order (interval DP)', 'There are O(n²) intervals, and each tries up to n split points.'),
  ('meeting-rooms', 'O(n log n)', 'rooms needed for meetings', 'Two sorts cost O(n log n). The sweep moves each pointer forward at most n times.'),
  ('memo-fib', 'O(n)', 'memoised Fibonacci', 'Each value from 0 to n is computed once and cached. Repeat calls are O(1) lookups.'),
  ('merge-intervals', 'O(n log n)', 'merge overlapping intervals', 'Sorting by start time is O(n log n). The merge sweep after it is linear.'),
  ('merge-sort', 'O(n log n)', 'merge sort', 'The input is split log n times, and each level of splitting does O(n) merging work.'),
  ('merge-sorted', 'O(n)', 'merge two sorted lists', 'Every element is copied exactly once. That is O(n + m), which is linear in the total input.'),
  ('mountain-peak', 'O(log n)', 'peak of a mountain array', 'Comparing mid with its right neighbour shows which half holds the peak, so half the range is dropped each time.'),
  ('move-zeros', 'O(n)', 'move zeros to the end', 'One pass compacts the non-zero values, and a second pass fills the tail with zeros.'),
  ('n-queens', 'O(n!)', 'count N-queens placements', 'Row 0 has n column choices, row 1 at most n − 1, and so on. Pruning helps in practice, but the bound stays n!.'),
  ('naive-fib', 'O(2ⁿ)', 'Fibonacci without memoisation', 'Each call makes two more, the depth is n, and nothing is cached. The tight bound is about 1.618ⁿ, which falls in the exponential class.'),
  ('neighbours', 'O(1)', 'count live neighbours', 'Exactly eight neighbours are checked for one cell, no matter how big the grid is.'),
  ('next-greater', 'O(n)', 'next greater element (stack)', 'The inner while pops, but each index is pushed once and popped at most once: about 2n operations in total.'),
  ('next-perm-loop', 'O(n!)', 'step through every ordering', 'The loop runs once for each distinct ordering, n! of them when the items are distinct. Each step is O(n) on top of that.'),
  ('no-adjacent-masks', 'O(2ⁿ)', 'bitmasks with no adjacent ones', 'The loop visits all 2ⁿ masks, and each check is O(1).'),
  ('pair-sum-brute', 'O(n²)', 'pair sum by brute force', 'The inner loop starts at i + 1, so the worst case is n(n − 1) / 2 checks. That is still quadratic.'),
  ('pair-sum-set', 'O(n)', 'pair sum with a set', 'Set lookups are O(1) on average, so one pass is enough. Compare this with the nested-loop version.'),
  ('pairs-below', 'O(n log n)', 'count pairs below a limit', 'The sort is O(n log n). The two-pointer sweep after it is O(n).'),
  ('palindrome', 'O(n)', 'palindrome check', 'The two ends move inward, so at most n / 2 comparisons are made.'),
  ('palindromic-substrings', 'O(n²)', 'count palindromic substrings', 'There are 2n − 1 centres, and each can expand up to about n / 2 steps.'),
  ('permutations', 'O(n!)', 'every permutation by slicing', 'There are n choices for the first slot, n − 1 for the next, and so on: n! orderings. Copying adds a factor of n, but the factorial dominates.'),
  ('pow2', 'O(1)', 'power-of-two check', 'A single bit trick: a power of two has exactly one set bit, so n & (n - 1) clears it to zero.'),
  ('power-set', 'O(2ⁿ)', 'build the power set', 'The output doubles with every item, giving 2ⁿ subsets. Counting the copying it is n × 2ⁿ, but of these choices the class is exponential.'),
  ('powers-below', 'O(log n)', 'powers of two below n', 'p doubles on every iteration, so it passes n after about log₂ n steps.'),
  ('prefix-sums', 'O(n)', 'prefix sums', 'Each entry is built from the one before it in O(1).'),
  ('recursive-sum', 'O(n)', 'recursive sum by index', 'One call per element, each doing O(1) work: a recursion chain of depth n.'),
  ('reverse', 'O(n)', 'reverse in place', 'Two pointers meet in the middle after n / 2 swaps.'),
  ('ring-get', 'O(1)', 'ring buffer read', 'Modular arithmetic finds the slot directly. Nothing walks the buffer.'),
  ('search-each', 'O(n log n)', 'binary search for every item', 'There are n lookups, and each is a binary search costing log n.'),
  ('selection', 'O(n²)', 'selection sort', 'Each position scans the rest of the array for its minimum: n + (n − 1) + … + 1.'),
  ('smooth', 'O(n)', 'five-point smoothing', 'The inner loop always runs five times. n × 5 is still O(n).'),
  ('squares-up-to', 'O(√n)', 'perfect squares up to n', 'i stops once i² passes n, after about √n iterations.'),
  ('stack-push', 'O(1)', 'push and peek', 'Appending to the end of a dynamic array is amortised O(1): occasional resizes are paid for by the many cheap appends.'),
  ('staircase', 'O(n²)', 'build a text staircase', 'Building a string of i + 1 characters costs O(i) work. Summed over n rows, that is about n² / 2.'),
